  ('q_5212704fc29585e586e1', 'WEC', 'Examen 1', 4, 'Tema 4 · Funciones, arrays, métodos de array, objetos literales y JSON', 26, 'SOME, EVERY Y PREDICADOS BOOLEANOS · 4.3.5 · 4.3 (P. 9)', 'introduccion', '¿Qué devuelve some(predicado)?', '{"A": "true si al menos un elemento cumple", "B": "El número de elementos que cumplen", "C": "true solo si todos cumplen", "D": "El primer elemento encontrado"}'::jsonb, 'A', 'some plantea una pregunta existencial.'),
  ('q_0fc5c81b7cf5a39d9b25', 'WEC', 'Examen 1', 4, 'Tema 4 · Funciones, arrays, métodos de array, objetos literales y JSON', 26, 'SOME, EVERY Y PREDICADOS BOOLEANOS · 4.3.5 · 4.3 (P. 9)', 'introduccion', '¿Qué devuelve every(predicado)?', '{"A": "El primer índice válido", "B": "true si al menos uno cumple", "C": "Un array con booleanos", "D": "true si todos los elementos cumplen"}'::jsonb, 'D', 'every plantea una pregunta universal.'),
  ('q_b0a11b200ca3ade66c36', 'WEC', 'Examen 1', 4, 'Tema 4 · Funciones, arrays, métodos de array, objetos literales y JSON', 26, 'SOME, EVERY Y PREDICADOS BOOLEANOS · 4.3.5 · 4.3 (P. 9)', 'entrenamiento', '¿Qué devuelve [7,4,9,3].some(n=>n<5)?', '{"A": "[4,3]", "B": "true", "C": "2", "D": "false"}'::jsonb, 'B', 'Al menos las notas 4 y 3 cumplen la condición.'),
