  ('q_29e256725b7ae14000c5', 'WEC', 'Examen 1', 4, 'Tema 4 · Funciones, arrays, métodos de array, objetos literales y JSON', 26, 'SOME, EVERY Y PREDICADOS BOOLEANOS · 4.3.5 · 4.3 (P. 9)', 'entrenamiento', '¿Qué devuelve [1,2,3].every(n=>n>0)?', '{"A": "3", "B": "false", "C": "true", "D": "[true,true,true]"}'::jsonb, 'C', 'Todos los elementos son positivos.'),
