  ('q_0510dd422c28da25b0ab', 'WEC', 'Examen 1', 4, 'Tema 4 · Funciones, arrays, métodos de array, objetos literales y JSON', 29, 'SORT, TOSORTED Y COMPARADORES · 4.3.7 · 4.3 (P. 16, 17, 18, 19)', 'entrenamiento', '¿Qué devuelve [10,1,20,5].sort((a,b)=>a-b)?', '{"A": "[1,5,10,20]", "B": "[20,10,5,1]", "C": "[10,1,20,5]", "D": "[1,10,20,5]"}'::jsonb, 'A', 'a-b ordena números ascendentemente.'),
